        other.setAttribute("aria-pressed", String(other === button));
    }

    const category = button.dataset.filter;
    const list = category === "all"
        ? events
        : events.filter((item) => item.category === category);
    for (const card of document.querySelectorAll("#events article")) {
        card.style.display = category === "all" || card.dataset.category === category ? "" : "none";
    }
});

renderEvents(events);

// 1. Menu
const menuToggle = document.querySelector(".menu-toggle");
const nav = document.querySelector("#site-nav");

function setMenuOpen(isOpen) {
    nav.classList.toggle("is-open", isOpen);
    menuToggle.setAttribute("aria-expanded", String(isOpen));
}

menuToggle.addEventListener("click", () => {
    setMenuOpen(!nav.classList.contains("is-open"));
});

document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && nav.classList.contains("is-open")) {
        setMenuOpen(false);
        menuToggle.focus();
    }
});

// 2. Theme
const THEME_KEY = "theme";
const themeToggle = document.querySelector(".theme-toggle");

function applyTheme(theme) {
    const isDark = theme === "dark";
    document.body.classList.toggle("theme-dark", isDark);
    themeToggle.setAttribute("aria-pressed", String(isDark));
}

applyTheme(localStorage.getItem(THEME_KEY) === "dark" ? "dark" : "light");

themeToggle.addEventListener("click", () => {
    const next = document.body.classList.contains("theme-dark") ? "light" : "dark";
    localStorage.setItem(THEME_KEY, next);
    applyTheme(next);
});

// 3. Events
function renderEvents(list) {
    const container = document.querySelector("#events");
    const status = document.querySelector("#events-status");
    container.textContent = "";

    for (const item of list) {
        const card = document.createElement("article");
        card.classList.add("event");
        card.dataset.category = item.category;

        const title = document.createElement("h3");
        title.textContent = item.title;

        const date = document.createElement("p");
        date.classList.add("event__date");
        date.textContent = item.date;

        card.append(title, date);
        container.append(card);
    }

    status.textContent = list.length === 0
        ? "No events in this category yet"
        : `Shown: ${list.length}`;
}

// 4. Filter
const filters = document.querySelector(".filters");

filters.addEventListener("click", (event) => {
    const button = event.target.closest("[data-filter]");
    if (!button) {
        return;
    }

    for (const other of filters.querySelectorAll("[data-filter]")) {
        other.setAttribute("aria-pressed", String(other === button));
    }

    const category = button.dataset.filter;
    const list = category === "all"
        ? events
        : events.filter((item) => item.category === category);
    renderEvents(list);
});
